css:
.d-sk{width:180px;display:flex;flex-direction:column;gap:8px}
.d-sk i{height:12px;border-radius:6px;background:linear-gradient(90deg,color-mix(in srgb,var(--ink) 8%,transparent),color-mix(in srgb,var(--ink) 16%,transparent),color-mix(in srgb,var(--ink) 8%,transparent));background-size:200% 100%;animation:d-skeleton-shim 1.2s linear infinite}
.d-sk i:nth-child(2){width:80%}.d-sk i:nth-child(3){width:60%}
@keyframes d-skeleton-shim{to{background-position:-200% 0}}
.d-btn{font:inherit;font-size:13px;padding:8px 16px;border-radius:10px;border:1px solid var(--line);background:var(--paper);color:var(--ink);cursor:pointer;transition:transform 180ms var(--linear),background-color 180ms,color 180ms,border-color 180ms}
.d-btn:hover{box-shadow:0 6px 18px #20241e14}
.d-btn:active{transform:scale(.97)}

init:
root => root.querySelector('[data-swap]')?.addEventListener('click', () => {
    const box = root.querySelector('.d-sk');
    box.innerHTML = '<i style="background:var(--lime);animation:none;height:14px"></i><i style="background:color-mix(in srgb,var(--ink) 20%,transparent);animation:none"></i><i style="background:color-mix(in srgb,var(--ink) 12%,transparent);animation:none"></i>';
  })
